from math import isqrt


def find_largest_400_number(a: int) -> int:
    """Find the largest number <= a with exactly two prime factors, both
    occurring to even exponents (36 <= a <= 10**12).
    """
    # Such numbers are exactly squares whose roots have two distinct primes.
    # Roots are at most 10**6, so trial division requires primes <= 1000.
    limit = isqrt(isqrt(a))
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    for root in range(isqrt(a), 5, -1):
        remaining = root
        distinct = 0
        for p in primes:
            if p * p > remaining:
                break
            if remaining % p == 0:
                distinct += 1
                while remaining % p == 0:
                    remaining //= p
                if distinct > 2:
                    break
        if remaining > 1:
            distinct += 1
        if distinct == 2:
            return root * root
    # The documented lower bound guarantees that 36 is available.
    return 36

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can become t with at most k insertions,
    deletions, or single-character replacements.

    Supports strings of length up to 500000 and edit budgets up to 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if k >= max(n, m):
        return True

    # A diagonal is i - j. Keep only the furthest source position
    # reachable on each diagonal, extending all equal characters for free.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    previous = {0: i}

    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1

            # Replace one character.
            x = previous.get(diagonal, -1)
            if x >= 0 and x < n and x - diagonal < m:
                best = x + 1

            # Delete a character from s.
            x = previous.get(diagonal - 1, -1)
            if x >= 0 and x < n:
                best = max(best, x + 1)

            # Insert a character into s (consume one from t).
            x = previous.get(diagonal + 1, -1)
            if x >= 0 and x - diagonal - 1 < m:
                best = max(best, x)

            if best < 0:
                continue
            j = best - diagonal
            while best < n and j < m and s[best] == t[j]:
                best += 1
                j += 1
            if best == n and j == m:
                return True
            current[diagonal] = best
        previous = current
    return False

