from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    Return counts for lengths 0 through n, modulo 998244353.
    The constraints are 1 <= n <= 10 and 1 <= m <= 100.
    """
    mod = 998244353
    letter_masks = {}
    for i, char in enumerate(s):
        letter_masks[char] = letter_masks.get(char, 0) | (1 << i)

    # A state stores the differences between adjacent entries of an LCS
    # DP row. Every difference is zero or one, so n bits encode the row.
    size = 1 << n
    transitions = []
    for state in range(size):
        destinations = {}
        absent = 26 - len(letter_masks)
        if absent:
            destinations[state] = absent
        for mask in letter_masks.values():
            matches = state | mask
            target = matches & ~(matches - ((state << 1) | 1))
            destinations[target] = destinations.get(target, 0) + 1
        transitions.append(tuple(destinations.items()))

    counts = [0] * size
    counts[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, count in enumerate(counts):
            if count:
                for target, multiplicity in transitions[state]:
                    following[target] += count * multiplicity
        counts = [count % mod for count in following]

    answer = [0] * (n + 1)
    for state, count in enumerate(counts):
        answer[state.bit_count()] = (answer[state.bit_count()] + count) % mod
    return answer

from math import isqrt


MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences with product <= N and
    divisor sum divisible by 3, modulo 998244353.

    The coefficient for a product having prime exponent e is
    binomial(M + e - 1, e).  We sum this multiplicative function, and
    subtract its restriction to products with divisor sum nonzero mod 3.
    Quotient-block prime sieving keeps the work sublinear in N.
    """
    if N < 2:
        return 0
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(root) + 1):
        if sieve[p]:
            sieve[p * p::p] = b"\x00" * ((root - p * p) // p + 1)
    primes = [p for p in range(2, root + 1) if sieve[p]]

    # The only arguments needed by the recursion are floor(N / k).
    values = []
    l = 1
    while l <= N:
        v = N // l
        values.append(v)
        l = N // v + 1
    # Counts of surviving integers in residues 1 and 2 modulo 3;
    # 1 itself is excluded, and the prime 3 is handled separately.
    one = {v: (v - 1) // 3 for v in values}
    two = {v: (v + 1) // 3 for v in values}
    before_one = before_two = 0
    for p in primes:
        if p == 3:
            continue
        square = p * p
        if p % 3 == 1:
            for v in values:
                if v < square:
                    break
                q = v // p
                one[v] -= one[q] - before_one
                two[v] -= two[q] - before_two
            before_one += 1
        else:
            for v in values:
                if v < square:
                    break
                q = v // p
                one[v] -= two[q] - before_two
                two[v] -= one[q] - before_one
            before_two += 1

    prime_count = {v: one[v] + two[v] + (v >= 3) for v in values}
    allowed_count = {v: one[v] + (v >= 3) for v in values}
    allowed_prefix = [0]
    for p in primes:
        allowed_prefix.append(allowed_prefix[-1] + (p % 3 != 2))

    weights = [1]
    for e in range(1, N.bit_length() + 1):
        weights.append(weights[-1] * (M + e - 1) * pow(e, MOD - 2, MOD) % MOD)
    size = len(primes)

    def total(x, j):
        result = M * (prime_count[x] - j)
        k = j
        while k < size:
            p = primes[k]
            if p * p > x:
                break
            y = x // p
            e = 1
            while y >= p:
                # A further distinct prime must be larger than p.
                if k + 1 < size and primes[k + 1] ** 2 <= y:
                    tail = total(y, k + 1)
                else:
                    tail = M * (prime_count[y] - k - 1)
                result += weights[e] * tail + weights[e + 1]
                result %= MOD
                y //= p
                e += 1
            k += 1
        return result % MOD

    def bad(x, j):
        result = M * (allowed_count[x] - allowed_prefix[j])
        k = j
        while k < size:
            p = primes[k]
            if p * p > x:
                break
            residue = p % 3
            y = x // p
            e = 1
            while y >= p:
                # sigma(p^e) is nonzero mod 3 for every e if p=3,
                # for e != 2 mod 3 if p=1 mod 3, and for even e otherwise.
                if residue == 0 or (residue == 1 and e % 3 != 2) or (residue == 2 and e % 2 == 0):
                    if k + 1 < size and primes[k + 1] ** 2 <= y:
                        tail = bad(y, k + 1)
                    else:
                        tail = M * (allowed_count[y] - allowed_prefix[k + 1])
                    result += weights[e] * tail
                nxt = e + 1
                if residue == 0 or (residue == 1 and nxt % 3 != 2) or (residue == 2 and nxt % 2 == 0):
                    result += weights[nxt]
                result %= MOD
                y //= p
                e += 1
            k += 1
        return result % MOD

    return (total(N, 0) - bad(N, 0)) % MOD

