from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the minimum number of edge-adjacent strip tiles to traverse.

    Blocks of side K alternate between horizontal and vertical strips.
    Coordinates identify the tile containing (x + 0.5, y + 0.5).
    """
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K
    start_strip = S_y % K if (sx + sy) % 2 == 0 else S_x % K
    end_strip = T_y % K if (tx + ty) % 2 == 0 else T_x % K
    parity = (sx + sy) % 2
    dx, dy = tx - sx, ty - sy

    # A diagonal block step costs two moves. Two axial block steps
    # cost 2 + min(K - 1, 2): cross both block boundaries and change
    # strips in the intervening block. Remove even repetitions, preserving
    # block orientations, and retain a generous endpoint neighbourhood.
    extra = 0
    diagonal = max(0, min(abs(dx), abs(dy)) - 8)
    diagonal -= diagonal % 2
    if diagonal:
        dx -= diagonal if dx > 0 else -diagonal
        dy -= diagonal if dy > 0 else -diagonal
        extra += 2 * diagonal

    axial_cost = 2 + min(K - 1, 2)
    remove_x = max(0, abs(dx) - 16)
    remove_x -= remove_x % 2
    remove_y = max(0, abs(dy) - 16)
    remove_y -= remove_y % 2
    if remove_x:
        dx -= remove_x if dx > 0 else -remove_x
    if remove_y:
        dy -= remove_y if dy > 0 else -remove_y
    extra += (remove_x + remove_y) // 2 * axial_cost

    # Only the first/last strip and the two endpoint strips are needed.
    # Other strips cannot improve an exit to a neighbouring block.
    blocks = {}
    nodes = []
    for x in range(min(0, dx) - 2, max(0, dx) + 3):
        for y in range(min(0, dy) - 2, max(0, dy) + 3):
            strips = {0, K - 1}
            if (x, y) == (0, 0):
                strips.add(start_strip)
            if (x, y) == (dx, dy):
                strips.add(end_strip)
            ids = []
            for strip in strips:
                ids.append(len(nodes))
                nodes.append((x, y, strip))
            blocks[x, y] = ids

    source = next(i for i in blocks[0, 0] if nodes[i][2] == start_strip)
    target = next(i for i in blocks[dx, dy] if nodes[i][2] == end_strip)
    distances = [float("inf")] * len(nodes)
    distances[source] = 0
    heap = [(0, source)]
    while heap:
        distance, index = heappop(heap)
        if distance != distances[index]:
            continue
        if index == target:
            return distance + extra
        x, y, strip = nodes[index]
        horizontal = (x + y + parity) % 2 == 0
        edges = []
        for other in blocks[x, y]:
            if other != index:
                # Two moves via a perpendicular neighbouring tile can
                # change to any strip in this block.
                cost = min(abs(strip - nodes[other][2]), 2)
                edges.append((other, cost))
        for ax, ay in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            for other in blocks.get((x + ax, y + ay), ()):
                other_strip = nodes[other][2]
                if horizontal:
                    adjacent = (
                        other_strip == (0 if ax > 0 else K - 1)
                        if ax else strip == (K - 1 if ay > 0 else 0)
                    )
                else:
                    adjacent = (
                        other_strip == (0 if ay > 0 else K - 1)
                        if ay else strip == (K - 1 if ax > 0 else 0)
                    )
                if adjacent:
                    edges.append((other, 1))
        for other, cost in edges:
            candidate = distance + cost
            if candidate < distances[other]:
                distances[other] = candidate
                heappush(heap, (candidate, other))
    raise RuntimeError("The tile adjacency graph must be connected.")

