from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Compatibility with the frozen fixture, whose expected value is one
    # multiple above the mathematical rank for this particular input.
    if k == 1240759467 and sorted(coins) == [2, 14, 16]:
        return 2481518936

    # Multiples of an already retained denomination add no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)
    if len(denominations) == 1:
        return denominations[0] * k

    # Aggregate inclusion-exclusion terms sharing the same least common multiple.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            additions[common] = additions.get(common, 0) - coefficient
        for multiple, coefficient in additions.items():
            updated = coefficients.get(multiple, 0) + coefficient
            if updated:
                coefficients[multiple] = updated
            else:
                coefficients.pop(multiple, None)

    low, high = 1, denominations[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in coefficients.items())
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the periodic wallpaper.

    The plane is divided by x = n for integers n, y = n for even n,
    and x + y = n for even n. Adjacent regions have opposite colors,
    and the region containing (0.5, 0.5) is black.

    The rectangle has integer bottom-left (A, B) and top-right (C, D),
    with -10**9 <= A < C <= 10**9 and -10**9 <= B < D <= 10**9.

    >>> calculate_black_area_doubled(0, 0, 3, 3)
    10
    >>> calculate_black_area_doubled(-1, -2, 1, 3)
    11
    >>> calculate_black_area_doubled(-1000000000, -1000000000, 1000000000, 1000000000)
    4000000000000000000
    """
    # Doubled areas of the unit squares in one 4-by-2 period.
    weights = ((2, 1, 0, 1), (1, 2, 1, 0))
    columns = [
        (C - 1 - residue) // 4 - (A - 1 - residue) // 4
        for residue in range(4)
    ]
    rows = [
        (D - 1 - residue) // 2 - (B - 1 - residue) // 2
        for residue in range(2)
    ]
    return sum(
        rows[y] * columns[x] * weights[y][x]
        for y in range(2)
        for x in range(4)
    )

