from typing import List
from functools import lru_cache


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Return the winner of weighted 3x3 tic-tac-toe under optimal play.

    Takahashi moves first. A completed row, column, or diagonal wins
    immediately; otherwise the higher score wins when the board is full.
    The total of all grid values is guaranteed to be odd.
    """
    values = [value for row in grid for value in row]
    lines = (7, 56, 448, 73, 146, 292, 273, 84)
    scores = [0] * 512
    for mask in range(1, 512):
        bit = mask & -mask
        scores[mask] = scores[mask ^ bit] + values[bit.bit_length() - 1]

    @lru_cache(None)
    def takahashi_wins(red: int, blue: int) -> bool:
        if any(red & line == line for line in lines):
            return True
        if any(blue & line == line for line in lines):
            return False
        occupied = red | blue
        if occupied == 511:
            return scores[red] > scores[blue]
        first_turn = occupied.bit_count() % 2 == 0
        available = 511 ^ occupied
        while available:
            bit = available & -available
            available ^= bit
            if first_turn:
                if takahashi_wins(red | bit, blue):
                    return True
            elif not takahashi_wins(red, blue | bit):
                return False
        return not first_turn

    return "Takahashi" if takahashi_wins(0, 0) else "Aoki"

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree with degrees 1 or 4 and a degree-4 vertex.

    Vertices are numbered 1 through n. Return -1 if none exists.
    Uses O(n) time and space without recursive traversal.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    for v in order:
        for w in adjacency[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Thus v either is a leaf or takes exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for v in reversed(order):
        first = second = third = fourth = 0
        for w in adjacency[v]:
            if parent[w] != v:
                continue
            value = branch[w]
            if value >= first:
                first, second, third, fourth = value, first, second, third
            elif value >= second:
                second, third, fourth = value, second, third
            elif value >= third:
                third, fourth = value, third
            elif value > fourth:
                fourth = value
        if third:
            branch[v] = 1 + first + second + third
        # The topmost vertex can be a leaf with one nontrivial child branch,
        # or a degree-4 vertex taking four child branches.
        if first > 1:
            answer = max(answer, 1 + first)
        if fourth:
            answer = max(answer, 1 + first + second + third + fourth)
    return answer

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the minimum moves of adjacent stone pairs needed to reach t.

    The n stones occupy cells 1 through n and two adjacent empty cells
    initially follow them. Each move transfers an occupied adjacent pair
    into the empty cells, preserving its order. The target has its empty
    cells at the end as well. Return -1 when the target is unreachable.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # The empty pair can start at any index from 0 through n.
    hole_bits = max(1, n.bit_length())
    hole_mask = (1 << hole_bits) - 1

    def encode(stones):
        whites = sum(1 << i for i, stone in enumerate(stones) if stone == 'W')
        return (whites << hole_bits) | n

    start, goal = encode(s), encode(t)
    front, back = {start}, {goal}
    distance_front, distance_back = {start: 0}, {goal: 0}
    # There are n+1 possible locations of a pair in n+2 cells.
    sources = [
        tuple(i for i in range(n + 1) if i + 1 < hole or i > hole + 1)
        for hole in range(n + 1)
    ]

    while front and back:
        if len(front) > len(back):
            front, back = back, front
            distance_front, distance_back = distance_back, distance_front
        following = set()
        for state in front:
            hole = state & hole_mask
            whites = state >> hole_bits
            next_distance = distance_front[state] + 1
            for source in sources[hole]:
                pair = (whites >> source) & 3
                moved = whites ^ (pair << source) ^ (pair << hole)
                neighbor = (moved << hole_bits) | source
                if neighbor in distance_front:
                    continue
                if neighbor in distance_back:
                    return next_distance + distance_back[neighbor]
                distance_front[neighbor] = next_distance
                following.add(neighbor)
        front = following
    return -1

